  "d.3ednu": "IA-BuB motorretik Unreal Engine 5-era berrikuntza osoa",
  "d.3m3q6c": "Eguzki-beroa, eta erupzioak minutu gutxiro.",
  "d.3wpyge": "Hamasei kilometro hiri Clyde ibaian, zeru gris baxuaren azpian. Benetako grabitatea, benetako airea, teilatuak eta garabiak: eutsi abiadurari eta ez hurbildu sudurra ibaira.",
  "d.4b5t91": "PERIHELION, 4 SOLAR RADII, jokoko menuko sektore-irudia. Jokoko pantaila-argazkia, 0.6.1 bertsioa",
  "d.4p55jj": "ontzi-klaseak",
  "d.4pqks5": "Jokoaren kodea BuB-era aldatzen da, Claude Code-rekin idatzitako motor berri batera. Joko-moduluak prototipotik pasatzen dira eta gero izena aldatzen zaie.",
  "d.4wz1ss": "Partida bakoitzaren aurretik (jokalari bakarra eta multijokalari-gela) LOADOUT pantaila, krosko- eta ezkutu-mailekin, ezkutu-kolorearekin, hardpoint bakoitzeko errenkadekin eta ANVIL hangarreko ontziekin.",
  "d.5h9ajx": "LASERRAK",
  "d.5zdnfb": "Hutsa: marruskadurarik ez.",
  "d.61r5q7": "10 NEEDLE DITUEN HANGAR-LEKUA",
  "d.6mw8fz": "AUTO moduan hasten diren laser- eta kanoi-dorretxo bateriak.",
  "d.6vf32z": "0 bertsioa (demoa) izoztuta: 8 ontzi-klase, laserrak eta segida-tiroak, THETA-7 asteroide-eremua.",
  "d.6wbq2y": "Eguzkiaren diskoa, mapen arakatzailerako irudi finkoa.",
  "d.709qra": "Eutsi sakatuta kargatzeko, askatu tiro egiteko. 50 % edo gehiagoko kargan askatzen bada, tiro egiten du; hortik behera bertan behera geratzen da.",
  "d.7a27ds": "Hardpoint-eserlekuak, sei suziriko segidak jarraipen-kamerarekin, bultzada bikoitza, ANVIL-en laser-segidak, 10 NEEDLE aliatu jaurtitzen dituen ANVIL hangarra, eta kamera-astinduaren graduatzailea.",
  "d.7xvt5u": "Dena IAz garatzen da BuB motorrean, Claude Code erabiliz.",
  "d.87vl1g": "Sare lokaleko multijokalaria (bilatu partidak Wi-Fi berean, ostatatu edo sartu gela batean, abiarazi elkarrekin; co-op uhinak eta denak denen aurka) eta hiru mapa berri: LUNA, EARTH ORBIT eta SOL.",
  "d.899luq": "THRESHER jokoko hangar-menuan ikusten den bezala, 0.6.1 bertsioko kroskoa, hiru laurdeneko ikuspegia hondo beltzean.",
  "d.90i5d3": "Eguraldia.",
  "d.99x268": "PATHFINDER jokoko hangar-menuan ikusten den bezala, 0.6.1 bertsioko kroskoa, hiru laurdeneko ikuspegia hondo beltzean.",
